definition.script:
node {
  def candidates = []
  if (env.PERFORMANCE_ROOT) {
    candidates.add(env.PERFORMANCE_ROOT)
    candidates.add("${env.PERFORMANCE_ROOT}/performance-execution")
  }
  candidates.add('/workspace/performance-execution')

  def selectedRoot = null
  for (candidate in candidates) {
    dir(candidate) {
      if (fileExists('jenkins/pipelines/Jenkinsfile')) {
        selectedRoot = candidate
      }
    }
    if (selectedRoot) {
      break
    }
  }

  if (!selectedRoot) {
    error "Could not find jenkins/pipelines/Jenkinsfile. Checked: ${candidates.join(', ')}"
  }

  dir(selectedRoot) {
    withEnv(["PERFORMANCE_ROOT=${selectedRoot}"]) {
      load 'jenkins/pipelines/Jenkinsfile'
    }
  }
}
